using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityMobileNightReview{static CityMobileNightReview(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityMobileNightReview.request"))return;File.Delete("CityMobileNightReview.request");try{var sc=SceneManager.GetActiveScene();var controller=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).Single();bool night=controller.IsNight;try{controller.ApplyNight();var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);cap.Invoke(null,new object[]{sc,new Vector3(-62,32,230),new Vector3(-62,31,320),"MobileOptimization/Street-Night"});cap.Invoke(null,new object[]{sc,new Vector3(-32,58,-351.9f),new Vector3(-115,36,-351.9f),"MobileOptimization/Hospital-Night"});}finally{if(night)controller.ApplyNight();else controller.ApplyDay();}EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/MobileOptimization/NightReview.txt","SUCCESS day/night toggle rendered both optimized street and hospital views; original lighting state restored. Existing lighting presets unchanged.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/MobileOptimization/NightReview.txt",e.ToString());}}}
